{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 detailed monitoring is disabled",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The three EC2 instances do not enable detailed monitoring, reducing the granularity of operational and security telemetry."
    },
    {
      "check_id": "CKV_AWS_135",
      "title": "EC2 instances are not EBS optimized",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The EC2 declaration does not explicitly enable EBS optimization for its instances."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "EC2 instances permit IMDSv1",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "No metadata options require IMDSv2, allowing the instances to accept less secure IMDSv1 requests."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 root volumes are not explicitly encrypted",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The root EBS volumes do not explicitly enable encryption, so data at rest could be created without encryption depending on account defaults."
    },
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance receives a public IP address",
      "resource": "aws_instance.ubuntu[1]",
      "severity": "MEDIUM",
      "explanation": "The instance at count index 1 is explicitly assigned a public IP address, increasing its potential exposure to internet-originated traffic."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "EC2 instances have no IAM role",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The EC2 instances have no IAM instance profile attached. A role with no permissions is attached so future AWS access can be granted through scoped role policies rather than instance credentials."
    }
  ],
  "patched_code": "resource \"aws_iam_role\" \"ubuntu\" {\n  name_prefix = \"ubuntu-ec2-\"\n\n  assume_role_policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [\n      {\n        Effect = \"Allow\"\n        Principal = {\n          Service = \"ec2.amazonaws.com\"\n        }\n        Action = \"sts:AssumeRole\"\n      }\n    ]\n  })\n}\n\nresource \"aws_iam_instance_profile\" \"ubuntu\" {\n  name_prefix = \"ubuntu-ec2-\"\n  role        = aws_iam_role.ubuntu.name\n}\n\nresource \"aws_instance\" \"ubuntu\" {\n  count                       = 3\n  ami                         = data.aws_ami.ubuntu_14_04.image_id\n  instance_type               = \"t2.micro\"\n  associate_public_ip_address = false\n  subnet_id                   = aws_subnet.my_subnet.id\n  monitoring                  = true\n  ebs_optimized               = true\n  iam_instance_profile        = aws_iam_instance_profile.ubuntu.name\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}\n",
  "fix_summary": "Disabled public IP assignment, enabled detailed monitoring, EBS optimization, root-volume encryption, and enforced IMDSv2. Added a permissionless EC2 IAM role and instance profile so scoped permissions can be attached without using static credentials."
}
